import { Download } from "lucide-react";
import OptionNumber from "@/components/brand/OptionNumber";

const DIR = "/brand/options";

// New options built on the 66° rule. Generated by brand-brinding/options-66/build_options.py —
// change the geometry there and re-export rather than editing the SVGs by hand.
// `w`/`h` are each file's viewBox; `unit` is the on-screen size of one drawing unit, in px.
const WORDMARKS = [
];

const MARKS = [
  {
    key: "forward",
    no: 10,
    w: 138.5,
    h: 100,
    ar: { name: "الخط ثم B", body: "الخط البرتقالي، وبعده B يميل بالزاوية نفسها." },
    en: { name: "Stroke, then B", body: "The Ember stroke, followed by a B leaning at the same angle." },
  },
];

const copy = {
  ar: {
    direction: "rtl",
    rule: [
      { big: "B", title: "من الحرف B", body: "رمز الحرف B في جدول ASCII هو 66." },
      { big: "66°", title: "الرقم يصير زاوية", body: "كل خط مائل وكل قصّة \u200E66° عن خط القاعدة، أو انعكاسها." },
      { big: "∠", title: "الزاوية فقط", body: "الرقم 66 لا يُرسم ولا يظهر شكلًا في أي خيار." },
    ],
    diagram: "زاوية \u200E66° عن خط القاعدة",
    wordmarksTitle: "خيارات الاسم",
    wordmarksNote: "شكل للاسم.",
    marksTitle: "خيارات الرمز",
    marksNote: "رمز لحرف B يصلح أيقونةً وصورة حساب. تظهر هنا بأحجام 96 و48 و24 بكسل.",
    where: "أين الـ\u200E66°",
    status: "قيد المراجعة",
    note: "كل الخيارات مرسومة من خطوط أفقية ورأسية وخطوط بزاوية \u200E66° فقط. الشعار المعتمد أعلاه لم يتغيّر.",
  },
  en: {
    direction: "ltr",
    rule: [
      { big: "B", title: "From the letter B", body: "The letter B is 66 in the ASCII table." },
      { big: "66°", title: "The number becomes an angle", body: "Every diagonal and every cut runs at 66° from the baseline, or its mirror." },
      { big: "∠", title: "The angle only", body: "The number 66 is never drawn and never appears as a shape in any option." },
    ],
    diagram: "66° from the baseline",
    wordmarksTitle: "Wordmark options",
    wordmarksNote: "One shape for the name.",
    marksTitle: "Mark options",
    marksNote: "A B mark that works as an icon and an avatar. Shown here at 96, 48 and 24 px.",
    where: "Where the 66° is",
    status: "Under review",
    note: "Every option is drawn from horizontals, verticals and 66° lines only. The approved logo above is unchanged.",
  },
};

function Chip({ href, label, tone = "dark" }) {
  const tones = {
    dark: "border-white/15 bg-white/5 text-[#F7F1E6] hover:border-[#E85A24] hover:text-[#F2A12C]",
    light: "border-[#150C09]/15 bg-[#150C09]/5 text-[#150C09] hover:border-[#150C09]/40",
  };
  return (
    <a
      href={href}
      download
      className={`inline-flex min-h-9 items-center gap-1.5 rounded-lg border px-3 text-xs font-semibold transition duration-200 motion-reduce:transition-none ${tones[tone]}`}
    >
      <Download className="h-3.5 w-3.5" aria-hidden="true" />
      <span className="latin">{label}</span>
    </a>
  );
}

/** The rule in one picture: a baseline, the Ember stroke, and the angle between them. */
function AngleDiagram({ label }) {
  return (
    <svg viewBox="0 0 240 150" role="img" aria-label={label} className="h-auto w-full max-w-[15rem]" focusable="false">
      <path d="M24 130 L68.52 30 L92.52 30 L48 130 Z" fill="#E85A24" />
      <path d="M12 130 H228" stroke="#F7F1E6" strokeOpacity="0.45" strokeWidth="1.5" />
      <path d="M88 130 A40 40 0 0 0 64.27 93.46" fill="none" stroke="#F7F1E6" strokeWidth="1.5" />
      <text x="98" y="114" fill="#F7F1E6" fontSize="17" fontWeight="700" className="latin">66°</text>
    </svg>
  );
}

function Wordmark({ item, language, text }) {
  const label = item[language];
  const unit = item.unit ?? 0.66;
  const file = `${DIR}/brxel-66-${item.key}`;

  return (
    <li className="flex flex-col overflow-hidden rounded-3xl border border-hairline bg-surface">
      <figure className="relative flex min-h-52 items-center justify-center bg-[#150C09] px-6 pb-10 pt-16" dir="ltr">
        <OptionNumber no={item.no} className="absolute start-3 top-3" />
        <div className="absolute end-3 top-3">
          <Chip href={`${file}-on-dark.svg`} label="SVG" />
        </div>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={`${file}-on-dark.svg`}
          alt={`BRXEL · ${label.name}`}
          width={item.w}
          height={item.h}
          loading="lazy"
          className="h-auto w-full"
          style={{ maxWidth: `${Math.round(item.w * unit)}px` }}
        />
      </figure>
      <figure className="flex min-h-24 items-center justify-between gap-4 bg-[#F7F1E6] px-5 py-5 sm:px-6" dir="ltr">
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={`${file}-on-light.svg`}
          alt=""
          width={item.w}
          height={item.h}
          loading="lazy"
          className="h-auto min-w-0 flex-1"
          style={{ maxWidth: `${Math.round(item.w * unit * 0.55)}px` }}
        />
        <Chip href={`${file}-on-light.svg`} label="SVG" tone="light" />
      </figure>
      <div className="flex-1 p-5 text-start sm:p-6">
        <h4 className="text-lg font-bold text-ice">{label.name}</h4>
        <p className="mt-2 text-sm leading-7 text-ice-muted">{label.body}</p>
        <p className="mt-4 text-xs font-semibold text-brand-bright">{text.where}</p>
        <p className="mt-1 text-sm leading-6 text-ice-muted">{label.where}</p>
      </div>
    </li>
  );
}

function Mark({ item, language }) {
  const label = item[language];
  const file = `${DIR}/brxel-66-mark-${item.key}`;

  return (
    <li className="flex flex-col overflow-hidden rounded-3xl border border-hairline bg-surface">
      <figure className="relative flex min-h-48 items-center justify-center bg-[#150C09] px-6 pb-8 pt-14" dir="ltr">
        <OptionNumber no={item.no} className="absolute start-3 top-3" />
        <div className="absolute end-3 top-3">
          <Chip href={`${file}-on-dark.svg`} label="SVG" />
        </div>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={`${file}-on-dark.svg`} alt={`BRXEL · ${label.name}`} width={item.w} height={item.h} loading="lazy" className="h-24 w-auto" />
      </figure>
      <div className="flex items-center justify-between gap-4 bg-[#F7F1E6] px-5 py-4" dir="ltr">
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={`${file}-on-light.svg`} alt="" width={item.w} height={item.h} loading="lazy" className="h-10 w-auto" />
        <div className="flex items-end gap-3">
          {[96, 48, 24].map((size) => (
            // eslint-disable-next-line @next/next/no-img-element
            <img key={size} src={`${file}-tile.svg`} alt="" width={size} height={size} loading="lazy" className="rounded-[18%]" style={{ width: size / 2, height: size / 2 }} />
          ))}
        </div>
      </div>
      <div className="flex-1 p-5 text-start sm:p-6">
        <h4 className="text-lg font-bold text-ice">{label.name}</h4>
        <p className="mt-2 text-sm leading-7 text-ice-muted">{label.body}</p>
      </div>
    </li>
  );
}

function Heading({ title, note, badge }) {
  return (
    <div className="flex flex-wrap items-end justify-between gap-2 text-start">
      <div>
        <h3 className="text-lg font-semibold text-ice">{title}</h3>
        <p className="mt-1 text-sm text-ice-muted">{note}</p>
      </div>
      <span className="rounded-full border border-brand/35 bg-brand/10 px-2.5 py-1 text-[11px] font-semibold text-brand-bright">{badge}</span>
    </div>
  );
}

/** New logo options, all built on one rule: B is 66 in ASCII, and 66° is the only angle used. */
export default function LogoOptions66({ locale = "ar" }) {
  const language = locale === "en" ? "en" : "ar";
  const text = copy[language];

  return (
    <div dir={text.direction} lang={language} className="mt-12">
      <div className="grid gap-4 rounded-3xl border border-brand/25 bg-[#0C0705] p-5 sm:p-7 lg:grid-cols-[minmax(0,1fr)_15rem] lg:items-center lg:gap-8">
        <ol className="grid gap-3 sm:grid-cols-3">
          {text.rule.map((step) => (
            <li key={step.title} className="rounded-2xl border border-white/10 bg-white/[0.025] p-4 text-start">
              <p className="latin text-3xl font-bold leading-none text-brand-bright">{step.big}</p>
              <p className="mt-4 text-sm font-semibold text-ice">{step.title}</p>
              <p className="mt-1 text-sm leading-6 text-ice-muted">{step.body}</p>
            </li>
          ))}
        </ol>
        <div className="flex justify-center" dir="ltr">
          <AngleDiagram label={text.diagram} />
        </div>
      </div>

      {WORDMARKS.length ? (
        <div className="mt-10">
          <Heading title={text.wordmarksTitle} note={text.wordmarksNote} badge={text.status} />
          <ol className="mt-5 grid gap-4 lg:grid-cols-2">
            {WORDMARKS.map((item) => (
              <Wordmark key={item.key} item={item} language={language} text={text} />
            ))}
          </ol>
        </div>
      ) : null}

      <div className="mt-10">
        <Heading title={text.marksTitle} note={text.marksNote} badge={text.status} />
        <ol className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {MARKS.map((item) => (
            <Mark key={item.key} item={item} language={language} />
          ))}
        </ol>
      </div>

      <div className="mt-6 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-hairline bg-surface p-5 text-start">
        <p className="max-w-2xl text-sm leading-7 text-ice-muted">{text.note}</p>
      </div>
    </div>
  );
}
